import sys, re
from pathlib import Path
sys.path.insert(0,'/Users/matthewsmith/Desktop/FIELD_FORGE_EXTERNAL_ESTATE_RETURN_R1/scripts')
from lib import *
import pyreadstat, openpyxl, warnings
warnings.filterwarnings('ignore')
T=[]; V=[]; VC=[]; C=[]; D=[]
p=ROOT/'Global Findex/GlobalFindexDatabase2025.dta'
df,m=pyreadstat.read_dta(str(p))
# glossary
wb=openpyxl.load_workbook(ROOT/'Global Findex/GlobalFindex2025-glossary.xlsx',read_only=True,data_only=True)
ws=wb['Glossary']; gloss={}
for s,name,definition in ws.iter_rows(min_row=2,values_only=True):
    if s: gloss[re.sub(r'[^a-z0-9]+','_',str(s).lower()).strip('_')]=(str(name),str(definition))
wb.close()
T.append(dict(source='FINDEX',es_id='ES12',release='Global Findex 2025 aggregate',table_or_object='Country-level five-wave aggregate',relative_path=str(p.relative_to(ROOT)),format='stata_dta',rows=m.number_rows,columns=m.number_columns,grain='country-wave-published-subgroup row; indicators are percentages or levels',key_columns='codewb + year + group + group2',units='percentages; population counts where named',universe='174 country codes; published subgroup margins; five waves 2011, 2014, 2017, 2021, 2024 (2022 observations within 2021 round)',dates='year field 2011, 2014, 2017, 2021, 2022, 2024',geography=f"{df['codewb'].nunique()} country codes",docs='GlobalFindex2025-glossary.xlsx; Survey-methodology.pdf; Findex-English.pdf; Connectivity-English.pdf; wave-specific glossaries/methodologies/questionnaires',read_status='INSPECTED',notes='Aggregate country-level dataset; no individual microdata. group/group2 identify published margins. Do not reconstruct joint distributions.'))
for c in m.column_names:
    g=gloss.get(re.sub(r'[^a-z0-9]+','_',c.lower()).strip('_'),('',''))
    lab=g[0] or str(c); definition=g[1] or ''
    role='key' if c in ('countrynewwb','codewb','year','group','group2') else ('selected_dimension' if c in ('account_t_d','fiaccount_t_d','mobileaccount_t_d','borrow_any_t_d','save_any_t_d','fin24aP','fin24aN','fin32','fin37_38','fin26a','fin26b','g20_any','internet','con1') else 'metadata')
    V.append(dict(source='FINDEX',es_id='ES12',release='Global Findex 2025 aggregate',table_or_object='Country-level five-wave aggregate',variable=c,label_or_definition=(lab+(': '+definition if definition else '')),storage_type=str(df[c].dtype),role=role,value_label_present='no',unit_or_scale=('percent' if c not in ('countrynewwb','codewb','year','pop_adult','group','group2','regionwb24_hi','incomegroupwb24') else ''),classification_or_denominator=('published subgroup row' if c in ('group','group2') else 'adults 15+ where applicable'),missing_or_special_states='NaN absent; published estimate only; no pseudo-joint reconstruction',docs_ref='GlobalFindex2025-glossary.xlsx',availability='observed',profile_scope='complete_metadata_census',notes='DTA variable label absent; glossary matched by normalized name where possible'))
for c in ['group','group2','regionwb24_hi','incomegroupwb24']:
    for val in sorted(set(str(v) for v in df[c].dropna().unique())):
        VC.append(dict(source='FINDEX',es_id='ES12',release='Global Findex 2025 aggregate',table_or_object='Country-level five-wave aggregate',variable=c,code=val,label=val,missing_or_special='',docs_ref='DTA group fields',used_in_selected_dimension='yes' if c in ('group','group2') else 'no'))
sel=['account_t_d','fiaccount_t_d','mobileaccount_t_d','borrow_any_t_d','save_any_t_d','fin24aP','fin24aN','fin32','fin37_38','fin26a','fin26b','g20_any','internet','con1']
for var in sel:
    for (iso,grp,grp2),g in df.groupby(['codewb','group','group2'],dropna=False):
        iso=str(iso); ys=g['year'].dropna().astype(int).tolist()
        C.append(dict(es_id='ES12',source='FINDEX',release='Global Findex 2025 aggregate',table_or_object='Country-level five-wave aggregate',variable_or_indicator=var,source_geo_id=iso,source_geo_label=str(g['countrynewwb'].iloc[0]),year_or_interval=ranges(ys),valid_count=int(g[var].notna().sum()),missing_count=int(g[var].isna().sum()),native_status_flags=f'group={grp}; group2={grp2}',country_grain='country-wave-subgroup',match_basis='iso3_code',roster_iso3=iso,roster_match='exact' if iso in ROSTER else 'not_in_roster',notes='published margin; no joint reconstruction'))
D.append(dict(es_id='ES12',requested_dimension='Financial access, saving/borrowing, emergency resource capacity, wage/transfer and digital access profiles',source='Global Findex',release='Global Findex 2025 aggregate',table_or_object='Country-level five-wave aggregate',variables_or_selector='account_t_d; fiaccount_t_d; mobileaccount_t_d; borrow_any_t_d; save_any_t_d; fin24aP; fin24aN; fin32; fin37_38; fin26a; fin26b; g20_any; internet; con1; group; group2',definition='published country-wave-subgroup percentages from the five-wave Findex aggregate',units_or_universe='published margins only; 174 country codes; five waves',date_semantics='survey wave year; 2022 observations belong to the 2021 round',geography_semantics='country code; regional/income aggregates may also appear',coverage_ref='COVERAGE_FINDEX.tsv',direct_proxy_absent='direct published aggregate, not individual or joint distribution',known_limitation='published subgroup margins only; no pseudo-joint or actor assignment; microdata deferred; country-level aggregates not individual behavior',evidence_ref='Findex DTA metadata, glossary and row-group inspection'))
write_tsv('TABLES_FINDEX.tsv',['source','es_id','release','table_or_object','relative_path','format','rows','columns','grain','key_columns','units','universe','dates','geography','docs','read_status','notes'],[[x.get(k,'') for k in ['source','es_id','release','table_or_object','relative_path','format','rows','columns','grain','key_columns','units','universe','dates','geography','docs','read_status','notes']] for x in T])
write_tsv('VARIABLES_FINDEX.tsv',['source','es_id','release','table_or_object','variable','label_or_definition','storage_type','role','value_label_present','unit_or_scale','classification_or_denominator','missing_or_special_states','docs_ref','availability','profile_scope','notes'],[[x.get(k,'') for k in ['source','es_id','release','table_or_object','variable','label_or_definition','storage_type','role','value_label_present','unit_or_scale','classification_or_denominator','missing_or_special_states','docs_ref','availability','profile_scope','notes']] for x in V])
write_tsv('VALUE_CODES_FINDEX.tsv',['source','es_id','release','table_or_object','variable','code','label','missing_or_special','docs_ref','used_in_selected_dimension'],[[x.get(k,'') for k in ['source','es_id','release','table_or_object','variable','code','label','missing_or_special','docs_ref','used_in_selected_dimension']] for x in VC])
write_tsv('COVERAGE_FINDEX.tsv',['es_id','source','release','table_or_object','variable_or_indicator','source_geo_id','source_geo_label','year_or_interval','valid_count','missing_count','native_status_flags','country_grain','match_basis','roster_iso3','roster_match','notes'],[[x.get(k,'') for k in ['es_id','source','release','table_or_object','variable_or_indicator','source_geo_id','source_geo_label','year_or_interval','valid_count','missing_count','native_status_flags','country_grain','match_basis','roster_iso3','roster_match','notes']] for x in C])
write_tsv('DIMENSION_MAP_FINDEX.tsv',['es_id','requested_dimension','source','release','table_or_object','variables_or_selector','definition','units_or_universe','date_semantics','geography_semantics','coverage_ref','direct_proxy_absent','known_limitation','evidence_ref'],[[x.get(k,'') for k in ['es_id','requested_dimension','source','release','table_or_object','variables_or_selector','definition','units_or_universe','date_semantics','geography_semantics','coverage_ref','direct_proxy_absent','known_limitation','evidence_ref']] for x in D])
